package com.bank.blocklist;

import java.util.*;
import java.util.logging.*;

public class NestedDemo {
    private static final Logger log = Logger.getLogger("BlockList");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> employeeIds = List.of(1, 2, 3, 4, 5);
        List<Integer> blocked = List.of(2, 4);
        BlockListService service = new BlockListService();

        log.info(() -> "nested (O(n*m)): " + service.blockedNested(employeeIds, blocked));
        log.info(() -> "set lookup O(n): " + service.blockedWithSet(employeeIds, blocked));
    }
}

// ─── Would be in service/BlockListService.java ───
class BlockListService {
    // ANTI-PATTERN: inner stream per outer element → O(n*m)
    List<Integer> blockedNested(List<Integer> ids, List<Integer> blocked) {
        return ids.stream()
            .filter(id -> blocked.stream().anyMatch(b -> b.equals(id)))  // re-streams per id
            .toList();
    }

    // FIX: precompute a Set once → O(1) contains → overall O(n)
    List<Integer> blockedWithSet(List<Integer> ids, List<Integer> blocked) {
        Set<Integer> blockedSet = new HashSet<>(blocked);                 // built once
        return ids.stream()
            .filter(blockedSet::contains)                                 // O(1) lookup
            .toList();
    }
}
